import Foundation
import Testing
@testable import PixlLibrary

/// The stage 1 golden vectors of the music brain (docs/brain-spec.md, 10.4). The files in `Fixtures/brain` are
/// GENERATED by the Android repo's `./gradlew :brain:generateGolden` and copied here unchanged; `README.md` beside
/// them says how each `fn` is replayed. The Swift core must reproduce every `out` from its `in`, byte for byte:
/// each test rebuilds the canonical `"out":{...}` text with `BrainJson.Writer` and compares it with the bytes of the
/// line. Never edit a golden file by hand; when the Kotlin changes, copy the folder again.
@Suite("Brain golden vectors (brainMatchesAndroid)")
struct BrainGoldenTests {
    typealias Value = BrainJson.Value

    // MARK: Reading

    static func fixtureData(_ name: String) throws -> Data {
        let base = (name as NSString).deletingPathExtension
        let ext = (name as NSString).pathExtension
        let url = try #require(Bundle.module.url(forResource: base, withExtension: ext.isEmpty ? nil : ext,
                                                 subdirectory: "Fixtures/brain"))
        return try Data(contentsOf: url)
    }

    static func lines(_ name: String) throws -> [String] {
        let text = String(decoding: try fixtureData(name), as: UTF8.self)
        return text.split(separator: "\n", omittingEmptySubsequences: true).map(String.init)
    }

    /// One line of a golden file: its kind, its parsed input, and the original bytes to compare against.
    struct Case {
        let fn: String
        let input: Value
        let line: String
        let number: Int

        /// True when the canonical `"out"` object that `build` writes is exactly the one in the file.
        func matches(_ build: (inout BrainJson.Writer) -> Void) -> Bool {
            var w = BrainJson.Writer()
            w.beginObject("out")
            build(&w)
            w.endObject()
            return line.hasSuffix("," + w.text + "}")
        }
    }

    static func cases(_ name: String) throws -> [Case] {
        var out: [Case] = []
        for (i, line) in try lines(name).enumerated() {
            let v = try BrainJson.parse(line)
            out.append(Case(fn: v["fn"]?.stringValue ?? "", input: try #require(v["in"]), line: line, number: i + 1))
        }
        return out
    }

    /// Collects the first failures of a file and reports them in one expectation.
    struct Report {
        let file: String
        var checked = 0
        var failures: [String] = []

        mutating func record(_ c: Case, _ ok: Bool) {
            checked += 1
            if !ok && failures.count < 5 { failures.append("\(file):\(c.number) \(c.fn): \(String(c.line.prefix(240)))") }
        }

        func verify(atLeast: Int) {
            #expect(failures.isEmpty, "\(failures.joined(separator: "\n"))")
            #expect(checked >= atLeast, "\(file): only \(checked) cases were replayed")
        }
    }

    // MARK: Small readers

    static func long(_ v: Value, _ k: String) -> Int64 { v[k]?.longValue ?? 0 }
    static func int(_ v: Value, _ k: String) -> Int32 { Int32(truncatingIfNeeded: v[k]?.bareLong ?? 0) }
    static func double(_ v: Value, _ k: String) -> Double { v[k]?.doubleValue ?? .nan }
    static func bool(_ v: Value, _ k: String) -> Bool { v[k]?.boolValue ?? false }
    static func string(_ v: Value, _ k: String) -> String { v[k]?.stringValue ?? "" }
    static func optionalString(_ v: Value, _ k: String) -> String? { v[k]?.stringValue }
    static func array(_ v: Value, _ k: String) -> [Value] { v[k]?.arrayValue ?? [] }
    static func longs(_ v: Value, _ k: String) -> [Int64] { array(v, k).map { $0.longValue ?? 0 } }

    static func events(_ v: Value, _ k: String) -> [PlayEvent] { array(v, k).compactMap { PlayEvent.decode($0) } }

    static func facts(_ input: Value) -> LibraryFacts {
        guard let f = input["facts"] else { return .empty }
        func i32(_ x: Value) -> Int32 { Int32(truncatingIfNeeded: x.bareLong ?? 0) }
        func i64(_ x: Value) -> Int64 { x.longValue ?? 0 }
        return LibraryFacts(
            liked: array(f, "liked").map { r in
                let a = r.arrayValue ?? []
                return LibraryFacts.TrackFact(rid: i64(a[0]), primaryAid: i64(a[1]))
            },
            topArtists: array(f, "topArtists").map { r in
                let a = r.arrayValue ?? []
                return LibraryFacts.TopArtist(aid: i64(a[0]), range: i32(a[1]), position: i32(a[2]), listSize: i32(a[3]))
            },
            topTracks: array(f, "topTracks").map { r in
                let a = r.arrayValue ?? []
                return LibraryFacts.TopTrack(rid: i64(a[0]), primaryAid: i64(a[1]), range: i32(a[2]), position: i32(a[3]),
                                             listSize: i32(a[4]))
            },
            followed: longs(f, "followed"),
            adjustments: array(f, "adjustments").map { r in
                let a = r.arrayValue ?? []
                return LibraryFacts.Adjustment(family: i32(a[0]), key: i64(a[1]), more: i32(a[2]) == 1, strength: i32(a[3]))
            }
        )
    }

    static func seeds(_ input: Value) -> [Retrieval.SeedList] {
        array(input, "seeds").map {
            Retrieval.SeedList(seedRid: long($0, "seedRid"), seedAid: long($0, "seedAid"), rids: longs($0, "rids"),
                               edgeFactor: double($0, "edgeFactor"))
        }
    }

    static func candidates(_ input: Value) -> [Candidate] {
        array(input, "candidates").map {
            Candidate(rid: long($0, "rid"), aid: long($0, "aid"), albumKey: long($0, "albumKey"),
                      inLibrary: bool($0, "inLibrary"), liked: bool($0, "liked"),
                      fromArtistRadio: bool($0, "fromArtistRadio"), boostLn: double($0, "boostLn"))
        }
    }

    // MARK: Small writers

    static func writeGraded(_ w: inout BrainJson.Writer, _ g: Reward.Graded) {
        w.double("r", g.r); w.double("c", g.c); w.double("cOther", g.cOther); w.int("rule", g.rule)
        w.bool("isSkip", g.isSkip); w.double("h", g.h)
    }

    static func writePlan(_ w: inout BrainJson.Writer, _ name: String, _ plan: StationPlanner.Plan?) {
        guard let plan else {
            w.nullValue(name)
            return
        }
        w.beginObject(name)
        w.beginArray("picks")
        for p in plan.picks {
            w.beginObject()
            w.long("rid", p.rid); w.int("arm", p.arm); w.int("slot", p.slot); w.int("slotKind", p.slotKind)
            w.string("why", WhyLine.nameOf(p.whyKey)); w.long("whyArg", p.whyArg); w.int("retrQ", p.retrQ)
            w.int("radioRank", p.radioRank); w.long("key", p.key); w.int("pQ", p.pQ); w.bool("novel", p.novel)
            w.endObject()
        }
        w.endArray()
        w.bool("usedLiked", plan.usedLiked); w.bool("usedFamiliarNext", plan.usedFamiliarNext)
        w.int("poolSize", plan.poolSize)
        w.endObject()
    }

    /// Every row of the state in canonical order, as the generator's `dump` prints it.
    static func dump(_ state: Affinity.State) -> String {
        var w = BrainJson.Writer()
        w.beginArray()
        for row in state.rows() {
            let k = row.counter
            w.beginArray()
            w.intItem(row.family); w.longItem(row.key); w.longItem(k.posQ); w.longItem(k.negQ); w.longItem(k.lastMs)
            w.longItem(k.posRQ); w.longItem(k.negRQ); w.longItem(k.lastRMs)
            w.endArray()
        }
        w.endArray()
        return w.text
    }

    // MARK: math.jsonl

    @Test func mathMatchesAndroid() throws {
        var report = Report(file: "math.jsonl")
        var counts: [String: Int] = [:]
        for c in try Self.cases("math.jsonl") {
            counts[c.fn, default: 0] += 1
            let x = Self.double(c.input, "x")
            switch c.fn {
            case "ln": report.record(c, c.matches { $0.double("y", BrainMath.ln(x)) })
            case "log2": report.record(c, c.matches { $0.double("y", BrainMath.log2(x)) })
            case "exp": report.record(c, c.matches { $0.double("y", BrainMath.exp(x)) })
            case "sigmoid": report.record(c, c.matches { $0.double("y", BrainMath.sigmoid(x)) })
            case "powNeg":
                let d = Self.double(c.input, "d")
                report.record(c, c.matches { $0.double("y", BrainMath.powNeg(x, d)) })
            case "toQ": report.record(c, c.matches { $0.long("q", BrainMath.toQ(x)) })
            case "orderKey": report.record(c, c.matches { $0.long("k", BrainMath.orderKey(x)) })
            case "localDay":
                let ms = Self.long(c.input, "ms")
                let tz = Self.int(c.input, "tzOffsetMin")
                report.record(c, c.matches {
                    let day = BrainMath.localDay(ms, tzOffsetMin: tz)
                    $0.long("day", day)
                    $0.int("weekday", BrainMath.weekday(day))
                    $0.bool("weekend", BrainMath.isWeekend(ms, tzOffsetMin: tz))
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 10_500)
        for fn in ["ln", "exp", "sigmoid", "log2", "powNeg"] { #expect(counts[fn] == 2000, "\(fn)") }
    }

    // MARK: hash.jsonl, fold.jsonl, title.jsonl

    @Test func hashMatchesAndroid() throws {
        var report = Report(file: "hash.jsonl")
        for c in try Self.cases("hash.jsonl") {
            switch c.fn {
            case "fnv1a64":
                let text = Self.string(c.input, "text")
                report.record(c, c.matches { $0.long("h", BrainHash.id(BrainHash.fnv1a64(text))) })
            case "fnv1a64Bytes":
                let hex = Array(Self.string(c.input, "hex").utf8)
                var bytes: [UInt8] = []
                var i = 0
                while i + 1 < hex.count {
                    let pair = String(decoding: hex[i..<(i + 2)], as: UTF8.self)
                    bytes.append(UInt8(pair, radix: 16) ?? 0)
                    i += 2
                }
                report.record(c, c.matches { $0.long("h", BrainHash.id(BrainHash.fnv1a64(bytes: bytes))) })
            case "splitmix64":
                let state = UInt64(bitPattern: Self.long(c.input, "state"))
                report.record(c, c.matches { $0.long("z", BrainHash.id(BrainHash.splitmix64(state))) })
            case "rng":
                let seed = UInt64(bitPattern: Self.long(c.input, "seed"))
                let n = Int(Self.int(c.input, "n"))
                report.record(c, c.matches {
                    var u = BrainHash.Rng(seed: seed)
                    var g = BrainHash.Rng(seed: seed)
                    $0.beginArray("uniform")
                    for _ in 0..<n { $0.doubleItem(u.uniform()) }
                    $0.endArray()
                    $0.beginArray("gaussian12")
                    for _ in 0..<n { $0.doubleItem(g.gaussian12()) }
                    $0.endArray()
                })
            case "unsigned":
                let h = Self.long(c.input, "h")
                let u = UInt64(bitPattern: h)
                report.record(c, c.matches {
                    $0.int("mod6", Int32(u % 6))
                    $0.int("mod10", Int32(u % 10))
                    $0.bool("lessThanMixed", BrainMath.compareUnsigned(h, BrainHash.id(BrainHash.splitmix64(u))) < 0)
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 900)
    }

