    // MARK: ids.jsonl

    @Test func idsMatchAndroid() throws {
        var report = Report(file: "ids.jsonl")
        var trackTable = Ids.MemoryAliasTable()
        let artistTable = Ids.MemoryAliasTable()
        for c in try Self.cases("ids.jsonl") {
            switch c.fn {
            case "nameKey":
                let key = Ids.nameKey(primaryArtist: Self.string(c.input, "artist"), rawTitle: Self.string(c.input, "title"))
                report.record(c, c.matches { w in
                    if let key { w.string("key", key) } else { w.nullValue("key") }
                })
            case "resolveTrack":
                if Self.int(c.input, "step") == 0 { trackTable = Ids.MemoryAliasTable() }
                let artist = Self.optionalString(c.input, "artist")
                let title = Self.optionalString(c.input, "title")
                var nameKey: String?
                if let artist, let title { nameKey = Ids.nameKey(primaryArtist: artist, rawTitle: title) }
                let keys = Ids.TrackKeys(spotifyId: Self.optionalString(c.input, "s"), isrc: Self.optionalString(c.input, "i"),
                                         videoId: Self.optionalString(c.input, "y"), nameKey: nameKey)
                let res = Ids.resolveTrack(keys, durationMs: Self.int(c.input, "durationMs"), table: trackTable)
                if let res { trackTable.apply(res) }
                report.record(c, c.matches { w in
                    guard let res else {
                        w.nullValue("rid")
                        return
                    }
                    w.long("rid", res.id); w.bool("minted", res.minted)
                    w.beginArray("aliases")
                    for a in res.aliases {
                        w.beginObject(); w.string("key", a.key); w.long("id", a.id); w.int("durationMs", a.durationMs)
                        w.endObject()
                    }
                    w.endArray()
                    w.beginArray("merges")
                    for m in res.merges { w.beginObject(); w.long("from", m.from); w.long("into", m.into); w.endObject() }
                    w.endArray()
                })
            case "mint":
                let taken = Set(Self.longs(c.input, "taken"))
                let id = Ids.mint(Self.string(c.input, "key")) { taken.contains($0) }
                report.record(c, c.matches { $0.long("id", id) })
            case "resolveArtist":
                let keys = Ids.ArtistKeys(spotifyId: Self.optionalString(c.input, "sa"),
                                          youTubeChannelId: Self.optionalString(c.input, "ya"),
                                          name: Self.string(c.input, "name"))
                let res = Ids.resolveArtist(keys, table: artistTable)
                if let res { artistTable.apply(res) }
                report.record(c, c.matches { w in
                    guard let res else {
                        w.nullValue("aid")
                        return
                    }
                    w.long("aid", res.id); w.bool("minted", res.minted)
                    w.beginArray("aliases")
                    for a in res.aliases { w.stringItem(a.key) }
                    w.endArray()
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 340)
    }

    // MARK: reward.jsonl

    @Test func rewardMatchesAndroid() throws {
        var report = Report(file: "reward.jsonl")
        for c in try Self.cases("reward.jsonl") {
            guard c.fn == "grade", let value = c.input["event"], let e = PlayEvent.decode(value) else {
                report.record(c, false)
                continue
            }
            // The codec is part of the contract: the decoded event must encode to the very bytes of the line.
            let codecHolds = c.line.contains("\"event\":" + e.encode() + ",")
            let g = Reward.grade(e, Reward.Context(pastCompletions: Self.int(c.input, "pastCompletions"),
                                                   skipStreak: Self.int(c.input, "skipStreak")))
            report.record(c, codecHolds && c.matches { Self.writeGraded(&$0, g) })
        }
        report.verify(atLeast: 300)
        #expect(report.checked == 300)
    }

    // MARK: affinity.jsonl

    @Test func affinityMatchesAndroid() throws {
        var report = Report(file: "affinity.jsonl")
        var state = Affinity.State()
        var lastT: Int64 = 0
        var readsPrepared = false
        var rebuilds = 0
        for c in try Self.cases("affinity.jsonl") {
            switch c.fn {
            case "apply":
                if Self.int(c.input, "step") == 0 {
                    state = Affinity.State()
                    readsPrepared = false
                }
                let family = Self.int(c.input, "family")
                let key = Self.long(c.input, "key")
                lastT = Self.long(c.input, "tMs")
                Affinity.apply(&state, family: family, key: key, r: Self.double(c.input, "r"), c: Self.double(c.input, "c"),
                               part: Self.double(c.input, "part"), tMs: lastT)
                let snapshot = state
                report.record(c, c.matches { w in
                    let k = snapshot.counter(family, key) ?? Affinity.Counter()
                    w.long("posQ", k.posQ); w.long("negQ", k.negQ); w.long("lastMs", k.lastMs)
                    w.long("posRQ", k.posRQ); w.long("negRQ", k.negRQ); w.long("lastRMs", k.lastRMs)
                    w.long("sumPosQ", snapshot.sum(family).posQ); w.long("sumNegQ", snapshot.sum(family).negQ)
                    w.long("newestMs", snapshot.newestMs)
                })
            case "read":
                if !readsPrepared {
                    Affinity.apply(&state, family: Family.all, key: Family.allKey, r: 0.7, c: 3.0, part: 1.0, tMs: lastT)
                    state.addPrior(Family.track, 11, posQ: BrainMath.toQ(2.0), negQ: 0)
                    readsPrepared = true
                }
                let family = Self.int(c.input, "family")
                let key = Self.long(c.input, "key")
                let now = Self.long(c.input, "nowMs")
                let snapshot = state
                report.record(c, c.matches { w in
                    let p0 = Affinity.p0(snapshot, nowMs: now)
                    w.double("p0", p0)
                    w.double("aff", Affinity.aff(snapshot, family: family, key: key, nowMs: now, p0: p0))
                    w.double("affRecent", Affinity.affRecent(snapshot, family: family, key: key, nowMs: now, p0: p0))
                    w.double("share", Affinity.share(snapshot, family: family, key: key, nowMs: now))
                    w.double("weight", Affinity.weight(snapshot, family: family, key: key, nowMs: now))
                    w.bool("clockJumpedBack", Affinity.clockJumpedBack(snapshot, nowMs: now))
                })
            case "rebuild":
                rebuilds += 1
                let rebuilt = Replay.rebuild(Self.events(c.input, "events"), facts: Self.facts(c.input),
                                             nowMs: Self.long(c.input, "nowMs"))
                report.record(c, c.matches { $0.raw("state", Self.dump(rebuilt)) })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 12 * 46 + 6)
        #expect(rebuilds == 6)
    }

    // MARK: retrieval.jsonl

    @Test func retrievalMatchesAndroid() throws {
        var report = Report(file: "retrieval.jsonl")
        for c in try Self.cases("retrieval.jsonl") {
            switch c.fn {
            case "cooc":
                let nowMs = Self.long(c.input, "nowMs")
                let state = Replay.rebuild(Self.events(c.input, "events"), facts: Self.facts(c.input), nowMs: nowMs)
                let p0 = Affinity.p0(state, nowMs: nowMs)
                let table = Retrieval.cooc(Self.seeds(c.input), affinity: state, nowMs: nowMs, p0: p0)
                report.record(c, c.matches { w in
                    w.double("p0", p0)
                    w.beginArray("entries")
                    for rid in table.keys.sorted() {
                        let e = table[rid]!
                        w.beginObject(); w.long("rid", rid); w.double("cooc", e.cooc); w.int("bestRank", e.bestRank)
                        w.int("bestSeed", e.bestSeed); w.endObject()
                    }
                    w.endArray()
                })
            case "percentiles":
                let arms = Self.array(c.input, "arms").map { Int32(truncatingIfNeeded: $0.bareLong ?? 0) }
                let scores = Self.array(c.input, "scores").map { $0.doubleValue ?? .nan }
                let pct = Retrieval.percentiles(arms: arms, scores: scores)
                report.record(c, c.matches { w in
                    w.beginArray("pct")
                    for p in pct { w.doubleItem(p) }
                    w.endArray()
                })
            default: report.record(c, false)
            }
        }
        report.verify(atLeast: 42)
    }

    // MARK: session.jsonl

    @Test func sessionMatchesAndroid() throws {
        var report = Report(file: "session.jsonl")
        var stampsHold = true
        for c in try Self.cases("session.jsonl") {
            guard c.fn == "session" else {
                report.record(c, false)
                continue
            }
            let seeds = Self.seeds(c.input)
            let candidates = Self.candidates(c.input)
            let tz = Self.int(c.input, "tzOffsetMin")
            let station = Self.bool(c.input, "station")
            var affinity = Replay.rebuild(Self.events(c.input, "history"), facts: Self.facts(c.input),
                                          nowMs: Self.long(c.input, "nowMs"))
            var tracker = GradeTracker()
            var state = SessionState(nuStart: Session.nuDefault)
            if station {
                state.seed = seeds[0].seedRid
                state.seedAid = seeds[0].seedAid
                state.seedKind = Session.seedStationSong
            }
            var tail: [Int64] = []
            var played: Set<Int64> = []
            var out = BrainJson.Writer()
            out.beginArray()
            for (stepIndex, step) in Self.array(c.input, "steps").enumerated() {
                guard let value = step["event"], let e = PlayEvent.decode(value) else { continue }
                let fromTail = e.startReason == StartReason.autoplay
                let stamp = Session.begin(&state, startedAtMs: e.startedAtMs, startReason: e.startReason)
                if stamp.sessionId != e.sessionId || stamp.posInSession != e.posInSession || stamp.passiveRun != e.passiveRun {
                    stampsHold = false
                }
                let g = Brain.onEvent(affinity: &affinity, tracker: &tracker, session: &state, event: e)
                played.insert(e.rid)
                let t = e.endedAtMs + 500
                if fromTail && !tail.isEmpty { tail.removeFirst() }

                let graph = StationPlanner.buildGraph(seeds: seeds, candidates: candidates, session: state)
                let topUp = tail.isEmpty
                if topUp != Self.bool(step, "topUp") { stampsHold = false }
                let request = StationPlanner.Request(
                    mode: station ? StationPlanner.modeStation : StationPlanner.modeAutoplay,
                    count: topUp ? 5 : tail.count,
                    candidates: candidates,
                    seeds: seeds,
                    nowMs: t,
                    tzOffsetMin: tz,
                    tieSeed: state.sessionId ^ Int64(stepIndex),
                    excludedRids: played,
                    bridge: topUp && stepIndex < seeds.count + 1
                )
                let plan = topUp
                    ? StationPlanner.plan(request, affinity: affinity, session: state, graph: graph)
                    : Session.patchQueue(state, tail: tail, request: request, affinity: affinity, graph: graph)
                if let plan {
                    StationPlanner.consume(&state, plan)
                    tail = plan.picks.map(\.rid)
                }
                out.beginObject()
                out.beginObject("graded")
                Self.writeGraded(&out, g)
                out.endObject()
                out.raw("state", state.encode())
                Self.writePlan(&out, "plan", plan)
                out.longs("tail", tail)
                out.endObject()
            }
            out.endArray()
            let steps = out.text
            report.record(c, c.matches { $0.raw("steps", steps) })
        }
        report.verify(atLeast: 12)
        #expect(stampsHold, "Session.begin did not stamp a play the way the generator's did")
    }

    // MARK: lists.jsonl

    @Test func listsMatchAndroid() throws {
        var report = Report(file: "lists.jsonl")
        for c in try Self.cases("lists.jsonl") {
            guard c.fn == "plan", let r = c.input["request"] else {
                report.record(c, false)
                continue
            }
            let seeds = Self.seeds(c.input)
            let candidates = Self.candidates(c.input)
            var affinity = Replay.rebuild(Self.events(c.input, "history"), facts: Self.facts(c.input),
                                          nowMs: Self.long(c.input, "nowMs"))
            var tracker = GradeTracker()
            var state = SessionState(nuStart: Session.nuDefault)
            if Self.bool(c.input, "station") {
                state.seed = seeds[0].seedRid
                state.seedAid = seeds[0].seedAid
                state.seedKind = Session.seedStationSong
            }
            for e in Self.events(c.input, "session") {
                _ = Session.begin(&state, startedAtMs: e.startedAtMs, startReason: StartReason.tap)
                Brain.onEvent(affinity: &affinity, tracker: &tracker, session: &state, event: e)
            }
            let graph = StationPlanner.buildGraph(seeds: seeds, candidates: candidates, session: state)
            let prior = Self.array(r, "prior").map { row -> ListBuilder.Prior in
                let a = row.arrayValue ?? []
                return ListBuilder.Prior(rid: a[0].longValue ?? 0, aid: a[1].longValue ?? 0, albumKey: a[2].longValue ?? 0,
                                         novel: (a[3].bareLong ?? 0) == 1)
            }
            let request = StationPlanner.Request(
                mode: Self.int(r, "mode"),
                count: Int(Self.int(r, "count")),
                candidates: candidates,
                seeds: seeds,
                prior: prior,
                nowMs: Self.long(r, "nowMs"),
                tzOffsetMin: Self.int(r, "tzOffsetMin"),
                nuMultiplier: Self.double(r, "nuMultiplier"),
                tieSeed: Self.long(r, "tieSeed"),
                excludedRids: Set(Self.longs(r, "excludedRids")),
                bridge: Self.bool(r, "bridge"),
                finite: Self.bool(r, "finite")
            )
            let plan = StationPlanner.plan(request, affinity: affinity, session: state, graph: graph)
            let encodedState = state.encode()
            report.record(c, c.matches {
                $0.raw("sessionState", encodedState)
                Self.writePlan(&$0, "plan", plan)
            })
        }
        report.verify(atLeast: 30)
    }

    // MARK: The folder itself

    @Test func theManifestListsEveryFileWithItsHash() throws {
        let manifest = try Self.lines("MANIFEST.sha256")
        #expect(manifest.count == 33)
        for entry in manifest {
            let hash = String(entry.prefix(64))
            let name = String(entry.dropFirst(66))
            let digest = TestSHA256.hex(Array(try Self.fixtureData(name)))
            #expect(digest == hash, "\(name) is not the file Android generated (was it edited, or re-encoded with CRLF?)")
        }
    }

    @Test func theSpecVersionFileIsTheCodesVersion() throws {
        let text = String(decoding: try Self.fixtureData("SPEC_VERSION"), as: UTF8.self)
        #expect(text.trimmingCharacters(in: .whitespacesAndNewlines) == String(Brain.specVersion))
    }
}

/// A plain SHA-256 for the manifest check (the package's own lives in PixlBackup, which this target cannot import).
enum TestSHA256 {
    private static let k: [UInt32] = [
        0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
        0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
        0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
        0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
        0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
        0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
        0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
        0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
    ]

    static func rotr(_ x: UInt32, _ n: UInt32) -> UInt32 { (x >> n) | (x << (32 - n)) }

    static func hex(_ message: [UInt8]) -> String {
        var h: [UInt32] = [0x6a09e667, 0xbb67ae85, 0x3c6ef372, 0xa54ff53a, 0x510e527f, 0x9b05688c, 0x1f83d9ab, 0x5be0cd19]
        var data = message
        let bitLength = UInt64(message.count) &* 8
        data.append(0x80)
        while data.count % 64 != 56 { data.append(0) }
        for shift in stride(from: 56, through: 0, by: -8) { data.append(UInt8(truncatingIfNeeded: bitLength >> UInt64(shift))) }
        var w = [UInt32](repeating: 0, count: 64)
        var offset = 0
        while offset < data.count {
            for i in 0..<16 {
                let b = offset + i * 4
                let hi = UInt32(data[b]) << 24 | UInt32(data[b + 1]) << 16
                let lo = UInt32(data[b + 2]) << 8 | UInt32(data[b + 3])
                w[i] = hi | lo
            }
            for i in 16..<64 {
                let x = w[i - 15]
                let y = w[i - 2]
                let s0 = rotr(x, 7) ^ rotr(x, 18) ^ (x >> 3)
                let s1 = rotr(y, 17) ^ rotr(y, 19) ^ (y >> 10)
                w[i] = w[i - 16] &+ s0 &+ w[i - 7] &+ s1
            }
            var a = h[0], b = h[1], c = h[2], d = h[3], e = h[4], f = h[5], g = h[6], hh = h[7]
            for i in 0..<64 {
                let s1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25)
                let ch = (e & f) ^ (~e & g)
                let t1 = hh &+ s1 &+ ch &+ k[i] &+ w[i]
                let s0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22)
                let maj = (a & b) ^ (a & c) ^ (b & c)
                let t2 = s0 &+ maj
                hh = g; g = f; f = e; e = d &+ t1; d = c; c = b; b = a; a = t1 &+ t2
            }
            h[0] = h[0] &+ a; h[1] = h[1] &+ b; h[2] = h[2] &+ c; h[3] = h[3] &+ d
            h[4] = h[4] &+ e; h[5] = h[5] &+ f; h[6] = h[6] &+ g; h[7] = h[7] &+ hh
            offset += 64
        }
        let digits = Array("0123456789abcdef".utf8)
        var out: [UInt8] = []
        for word in h {
            for shift in stride(from: 28, through: 0, by: -4) { out.append(digits[Int((word >> UInt32(shift)) & 15)]) }
        }
        return String(decoding: out, as: UTF8.self)
    }
}
